import React, { useState } from 'react';
import chatBgImg from '../../assets/nen_khung_chat.jpg';

const QuanLyHoaDon = () => {
    // Lấy thời gian hiện tại để làm mặc định
    const now = new Date();
    const currentMonth = now.getMonth() + 1;
    const currentYear = now.getFullYear();

    const [selectedMonth, setSelectedMonth] = useState(currentMonth);
    const [selectedYear, setSelectedYear] = useState(currentYear);

    // Tạo danh sách năm (từ 2024 đến 2026)
    const years = [2024, 2025, 2026];
    const months = Array.from({ length: 12 }, (_, i) => i + 1);

    // Tạo danh sách 45 phòng (không cần state selectedRoom vì không cho chọn nữa)
    const allRooms = [];
    for (let floor = 1; floor <= 9; floor++) {
        for (let num = 1; num <= 5; num++) {
            allRooms.push(`${floor}0${num}`);
        }
    }

    // Kiểm tra xem tháng/năm đang chọn có phải là hiện tại hoặc tương lai không
    const isCurrentOrFuture = selectedYear > currentYear || (selectedYear === currentYear && selectedMonth >= currentMonth);

    // Tính toán tổng tiền
    const totalReceived = isCurrentOrFuture ? 0 : (5000000 * 45);

    return (
        <div style={{
            flex: 1, borderRadius: '30px', display: 'flex', flexDirection: 'column', 
            backgroundImage: `url(${chatBgImg})`, backgroundSize: 'cover',
            backgroundPosition: 'center', overflow: 'hidden'
        }} className="glass-card">

            <div style={{ padding: '20px', color: '#fff', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                <h2 style={{ margin: 0, textShadow: '1px 1px 4px rgba(0,0,0,0.5)' }}>Quản lý hoá đơn</h2>

                {/* Bộ lọc Năm và Tháng */}
                <div style={{ display: 'flex', gap: '10px' }}>
                    <select 
                        value={selectedMonth} 
                        onChange={(e) => setSelectedMonth(parseInt(e.target.value))}
                        style={{ padding: '8px', borderRadius: '10px', border: 'none', fontWeight: 'bold', cursor: 'pointer' }}
                    >
                        {months.map(m => <option key={m} value={m}>Tháng {m}</option>)}
                    </select>
                    <select 
                        value={selectedYear} 
                        onChange={(e) => setSelectedYear(parseInt(e.target.value))}
                        style={{ padding: '8px', borderRadius: '10px', border: 'none', fontWeight: 'bold', cursor: 'pointer' }}
                    >
                        {years.map(y => <option key={y} value={y}>Năm {y}</option>)}
                    </select>
                </div>
            </div>

            <div style={{ flex: 1, padding: '0 20px 20px 20px', display: 'flex', gap: '30px', overflow: 'hidden' }}>

                {/* CỘT TRÁI: DANH SÁCH PHÒNG (Chỉ hiển thị trạng thái, không thể chọn) */}
                <div style={{ 
                    width: '210px', display: 'grid', gridTemplateColumns: 'repeat(5, 1fr)', 
                    gap: '6px', alignContent: 'flex-start', overflowY: 'auto',
                    padding: '12px', backgroundColor: 'rgba(255,255,255,0.1)',
                    borderRadius: '20px', border: '1px solid rgba(255,255,255,0.1)'
                }}>
                    {allRooms.map(room => {
                        const isPaid = !isCurrentOrFuture;
                        // Vàng là chưa thanh toán, Trắng là đã thanh toán
                        const bgColor = isPaid ? 'rgba(255,255,255,0.8)' : '#ffcc00'; 

                        return (
                            <div 
                                key={room} 
                                style={{ 
                                    background: bgColor, 
                                    color: '#333',
                                    padding: '8px 0', borderRadius: '8px', textAlign: 'center', 
                                    fontSize: '11px', fontWeight: 'bold',
                                    border: '1px solid rgba(0,0,0,0.1)',
                                    cursor: 'default', // Đổi icon chuột thành mặc định để biết không thể click
                                    userSelect: 'none'
                                }}
                            >
                                {room}
                            </div>
                        );
                    })}
                </div>

                {/* CỘT PHẢI: CHI TIẾT HOÁ ĐƠN & LỊCH SỬ CUỘN */}
                <div style={{ 
                    flex: 1, backgroundColor: '#ffffff', borderRadius: '25px', 
                    padding: '25px', display: 'flex', flexDirection: 'column',
                    color: '#333', boxShadow: '0 8px 32px 0 rgba(0, 0, 0, 0.3)',
                    overflow: 'hidden'
                }}>
                    {/* Tổng tiền đã nhận */}
                    <div style={{ 
                        marginBottom: '20px', padding: '15px 20px', backgroundColor: '#f8f9fa', 
                        borderRadius: '15px', borderLeft: '5px solid #8b5e5e'
                    }}>
                        <span style={{ fontSize: '16px', fontWeight: 'bold', color: '#666' }}>Tổng tiền đã nhận trong tháng {selectedMonth}/{selectedYear}:</span>
                        <h2 style={{ margin: '5px 0 0 0', color: totalReceived > 0 ? '#28a745' : '#999', fontSize: '28px' }}>
                            {totalReceived.toLocaleString()}đ
                        </h2>
                    </div>

                    {/* Tiêu đề lịch sử */}
                    <h3 style={{ borderBottom: '2px solid #eee', paddingBottom: '10px', marginBottom: '0' }}>Lịch sử giao dịch</h3>

                    {/* KHU VỰC CUỘN (Tương tự khung chat) */}
                    <div style={{ 
                        flex: 1, 
                        overflowY: 'auto', 
                        marginTop: '10px',
                        paddingRight: '10px',
                        scrollbarWidth: 'thin' // Cho trình duyệt hiện đại
                    }}>
                        <table style={{ width: '100%', borderCollapse: 'collapse' }}>
                            <thead style={{ position: 'sticky', top: 0, backgroundColor: '#fff', zIndex: 1 }}>
                                <tr style={{ textAlign: 'left', color: '#888', fontSize: '13px' }}>
                                    <th style={{ padding: '12px', borderBottom: '2px solid #f1f1f1' }}>Phòng</th>
                                    <th style={{ padding: '12px', borderBottom: '2px solid #f1f1f1' }}>Số tiền</th>
                                    <th style={{ padding: '12px', borderBottom: '2px solid #f1f1f1' }}>Nội dung chuyển khoản</th>
                                    <th style={{ padding: '12px', borderBottom: '2px solid #f1f1f1' }}>Thời gian</th>
                                </tr>
                            </thead>
                            <tbody>
                                {!isCurrentOrFuture ? (
                                    allRooms.map(room => (
                                        <tr key={room} style={{ borderBottom: '1px solid #f8f8f8' }}>
                                            <td style={{ padding: '12px', fontWeight: 'bold' }}>{room}</td>
                                            <td style={{ padding: '12px', color: '#28a745', fontWeight: '500' }}>5,000,000đ</td>
                                            <td style={{ padding: '12px', fontSize: '13px' }}>
                                                Chuyển khoản tiền phòng tháng {selectedMonth} - năm {selectedYear}
                                            </td>
                                            <td style={{ padding: '12px', fontSize: '12px', color: '#999' }}>
                                                01/{selectedMonth.toString().padStart(2, '0')}/{selectedYear} 10:30
                                            </td>
                                        </tr>
                                    ))
                                ) : (
                                    <tr>
                                        <td colSpan="4" style={{ textAlign: 'center', padding: '60px', color: '#bbb', fontStyle: 'italic' }}>
                                            Chưa có dữ liệu thanh toán cho tháng này...
                                        </td>
                                    </tr>
                                )}
                            </tbody>
                        </table>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default QuanLyHoaDon;
